    public SecretValue read(String reference) {
        String value = environment.get(reference);
        if (value == null) throw new IllegalStateException("secret environment entry is unavailable");
        char[] characters = value.toCharArray();
        try {
            return SecretValue.fromUtf8(characters);
        } finally {
            java.util.Arrays.fill(characters, '\0');
        }
    }
}
